package com.huy.enterprise.shipment; import com.huy.enterprise.common.*; import com.huy.enterprise.common.enums.ShipmentStatus; import com.huy.enterprise.order.PurchaseOrderRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; @Service @RequiredArgsConstructor public class ShipmentService {private final ShipmentRepository repo;private final PurchaseOrderRepository orders; Shipment entity(UUID id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Shipment not found: "+id));}List<ShipmentResponse> all(){return repo.findAll().stream().map(ShipmentResponse::from).toList();}ShipmentResponse get(UUID id){return ShipmentResponse.from(entity(id));}@Transactional ShipmentResponse save(UUID id,ShipmentRequest r){if(id==null&&repo.existsByShipmentCode(r.shipmentCode()))throw new ConflictException("Shipment code already exists");var s=id==null?new Shipment():entity(id);s.setShipmentCode(r.shipmentCode());s.setPurchaseOrder(orders.findById(r.purchaseOrderId()).orElseThrow(()->new ResourceNotFoundException("Purchase order not found: "+r.purchaseOrderId())));s.setCarrierName(r.carrierName());s.setDepartureDate(r.departureDate());s.setExpectedArrivalDate(r.expectedArrivalDate());s.setActualArrivalDate(r.actualArrivalDate());s.setStatus(r.status()==null?ShipmentStatus.PENDING:r.status());s.setCurrentLocation(r.currentLocation());s.setNotes(r.notes());return ShipmentResponse.from(repo.save(s));}@Transactional ShipmentResponse status(UUID id,ShipmentStatusRequest r){var s=entity(id);s.setStatus(r.status());return ShipmentResponse.from(repo.save(s));}}
